"""R101 contract-fixture tests: generated bytes, never an industrial study.

A local callback is intentionally NOT a native trained model or a trusted
sandbox. These tests check hashes, explicit scope and fail-closed wiring.
"""
from __future__ import annotations

from copy import deepcopy
from pathlib import Path
import hashlib
import json

import pytest

from phm_design.industrial_contracts.sealed_executor import (
    SealedExecutionRejected, seal_fixture_execution, execute_fixture_pair,
)
from test_r99_design_review import _binary_measured_protocol


def _write(path, object_value):
    path.write_text(json.dumps(object_value, sort_keys=True), encoding="utf-8")


def _bundles(tmp_path, frozen):
    roots = {}
    for aid, marker in ((frozen["challenger_artifact_id"], "challenger"),
                        (frozen["baseline_artifact_id"], "baseline")):
        root = tmp_path / marker
        root.mkdir()
        _write(root / "model.json", {
            "schema": "phm.autogen.r101-fixture-model.v1",
            "fixture_id": marker, "not_a_trained_model": True})
        _write(root / "preprocessor.json", {
            "schema": "phm.autogen.r101-fixture-preprocessor.v1",
            "source_only": True, "mode": "identity_fixture"})
        _write(root / "graph.json", {
            "schema": "phm.autogen.r101-fixture-graph.v1",
            "stages": ["original_bytes_fixture"],
            "uses_protected_truth": False})
        roots[aid] = root
    return roots


def _fixture(tmp_path):
    eq, manifest, trial, raws, frozen = _binary_measured_protocol(tmp_path)
    roots = _bundles(tmp_path, frozen)
    return eq, manifest, trial, raws, frozen, roots


class InspectableTestOnlyRunner:
    """Never fits a model or receives truth. Hardcoded generated fixture rule."""
    def __init__(self, frozen):
        self.frozen = frozen
        self.seen = []

    def __call__(self, model, record_id, raw, bundle):
        assert not any("label" in value for value in bundle.keys())
        assert isinstance(raw, bytes)
        assert isinstance(record_id, str)
        assert bundle["model.json"]["not_a_trained_model"] is True
        self.seen.append((model, record_id, hashlib.sha256(raw).hexdigest()))
        correct = "HEALTHY" if raw[0] % 2 else "FAULT"
        label = (correct if model == self.frozen["challenger_artifact_id"]
                 else ("FAULT" if correct == "HEALTHY" else "HEALTHY"))
        return {"predicted_label": label}


def test_r101_exact_frozen_files_and_both_blind_invocations_with_r99_receipt(
        tmp_path):
    eq, manifest, trial, raws, frozen, roots = _fixture(tmp_path)
    seal = seal_fixture_execution(frozen, trial, roots)
    assert seal == seal_fixture_execution(frozen, trial, roots)
    assert seal["no_native_model_load"]
    assert not seal["provider_executable_independently_authenticated"]
    spy = InspectableTestOnlyRunner(frozen)
    result = execute_fixture_pair(
        seal, frozen, eq, manifest, trial, raws, roots,
        fixture_runner=spy, explicit_fixture_mode=True)
    assert len(spy.seen) == 12  # 6 VAL rows each, 2 synthetic callbacks
    assert result["status"] == (
        "SYNTHETIC_FIXTURE_INVOCATION_HASHED_NOT_NATIVE_ATTESTED")
    assert result["r99_directional_submission_signal_only"]
    assert len(result["receipt_sha256"]) == 64
    for row in result["execution"].values():
        assert row["number_of_executed_fixture_callbacks"] == 6
        assert len(row["prediction_stream_sha256"]) == 64
    assert result["observed_resources"]["both_models_combined_wall_seconds"] >= 0
    assert result["observed_resources"]["both_models_combined_process_cpu_seconds"] >= 0
    assert not result["observed_resources"]["resource_limits_enforced"]
    assert not result["predictions_cryptographically_bound_to_real_model_execution"]
    assert not result["independent_real_device_superiority_proven"]
    assert not result["eligible_for_stable"]


def test_r101_default_refuses_fixture_callback_without_explicit_test_mode(tmp_path):
    eq, manifest, trial, raws, frozen, roots = _fixture(tmp_path)
    runner = InspectableTestOnlyRunner(frozen)
    with pytest.raises(SealedExecutionRejected,
                       match="R101_NO_TRUSTED_NATIVE_RUNNER_FIXTURE_MODE_ONLY"):
        execute_fixture_pair(
            seal_fixture_execution(frozen, trial, roots),
            frozen, eq, manifest, trial, raws, roots, fixture_runner=runner)
    assert runner.seen == []


def test_r101_mutated_bundle_after_seal_refused_before_any_execution(tmp_path):
    eq, manifest, trial, raws, frozen, roots = _fixture(tmp_path)
    seal = seal_fixture_execution(frozen, trial, roots)
    p = roots[frozen["challenger_artifact_id"]] / "model.json"
    content = json.loads(p.read_text(encoding="utf-8"))
    content["fixture_id"] = "CHANGED_AFTER_SEALING"
    _write(p, content)
    runner = InspectableTestOnlyRunner(frozen)
    with pytest.raises(SealedExecutionRejected,
                       match="R101_SEAL_OR_REGISTERED_FILE_BYTES_CHANGED"):
        execute_fixture_pair(
            seal, frozen, eq, manifest, trial, raws, roots,
            fixture_runner=runner, explicit_fixture_mode=True)
    assert runner.seen == []


def test_r101_rejects_identical_challenger_and_baseline_bundle_bytes(tmp_path):
    eq, manifest, trial, raws, frozen, roots = _fixture(tmp_path)
    challenger = roots[frozen["challenger_artifact_id"]]
    baseline = roots[frozen["baseline_artifact_id"]]
    for name in ("model.json", "graph.json", "preprocessor.json"):
        (baseline / name).write_bytes((challenger / name).read_bytes())
    with pytest.raises(SealedExecutionRejected,
                       match="R101_CHALLENGER_AND_BASELINE_BUNDLES_IDENTICAL"):
        seal_fixture_execution(frozen, trial, roots)


def test_r101_rejects_native_joblib_or_pickle_without_untrusted_deserialization(
        tmp_path):
    eq, manifest, trial, raws, frozen, roots = _fixture(tmp_path)
    (roots[frozen["challenger_artifact_id"]] / "estimator.joblib").write_bytes(
        b"UNTRUSTED_PICKLE_SHOULD_NOT_BE_LOADED")
    with pytest.raises(SealedExecutionRejected,
                       match="R101_ONLY_SAFE_FIXTURE_JSON_FILES_ALLOWED"):
        seal_fixture_execution(frozen, trial, roots)


def test_r101_rejects_swapped_or_missing_registered_artifact_ids(tmp_path):
    eq, manifest, trial, raws, frozen, roots = _fixture(tmp_path)
    with pytest.raises(SealedExecutionRejected,
                       match="R101_EXACT_FROZEN_ARTIFACT_ID_SET_REQUIRED"):
        seal_fixture_execution(frozen, trial, {frozen["challenger_artifact_id"]:
                                                roots[frozen["challenger_artifact_id"]]})
    altered = deepcopy(frozen)
    altered["challenger_artifact_id"] = "unregistered-new-model"
    with pytest.raises(SealedExecutionRejected,
                       match="R101_R99_COMPARISON_DIGEST_OR_SCOPE_CHANGED"):
        seal_fixture_execution(altered, trial, roots)


def test_r101_missing_or_mutated_raw_bytes_fail_before_first_callback(tmp_path):
    eq, manifest, trial, raws, frozen, roots = _fixture(tmp_path)
    seal = seal_fixture_execution(frozen, trial, roots)
    victim = next(r for r in manifest["records"] if r["role"] == "VALIDATION")
    path = Path(raws[victim["record_id"]])
    path.write_bytes(path.read_bytes()[:-1] + b"Z")
    spy = InspectableTestOnlyRunner(frozen)
    with pytest.raises(ValueError, match="R99_ORIGINAL_RAW_BYTES_SHA_MISMATCH"):
        execute_fixture_pair(seal, frozen, eq, manifest, trial, raws, roots,
                             fixture_runner=spy, explicit_fixture_mode=True)
    assert spy.seen == []


@pytest.mark.parametrize("bad", [
    {"predicted_label": "INVENTED_FAULT"},
    {"predicted_label": "HEALTHY", "label": "FAULT"},
    {"predicted_label": True},
    {"predicted_label": None},
    "HEALTHY",
])
def test_r101_rejects_nonregistered_or_extra_prediction_fields(tmp_path, bad):
    eq, manifest, trial, raws, frozen, roots = _fixture(tmp_path)
    seal = seal_fixture_execution(frozen, trial, roots)
    def bad_runner(*args):
        return bad
    with pytest.raises(SealedExecutionRejected,
                       match="R101_RUNNER_RETURNED_INVALID_PREDICTION"):
        execute_fixture_pair(seal, frozen, eq, manifest, trial, raws, roots,
                             fixture_runner=bad_runner, explicit_fixture_mode=True)


def test_r101_callback_exception_is_fail_closed_not_a_partial_score(tmp_path):
    eq, manifest, trial, raws, frozen, roots = _fixture(tmp_path)
    seal = seal_fixture_execution(frozen, trial, roots)
    def bad_runner(*args):
        raise RuntimeError("test-only simulated runner failure")
    with pytest.raises(SealedExecutionRejected,
                       match="R101_REGISTERED_FIXTURE_RUNNER_ERROR"):
        execute_fixture_pair(seal, frozen, eq, manifest, trial, raws, roots,
                             fixture_runner=bad_runner, explicit_fixture_mode=True)


def test_r101_detects_model_file_mutated_during_fixture_invocation(tmp_path):
    eq, manifest, trial, raws, frozen, roots = _fixture(tmp_path)
    seal = seal_fixture_execution(frozen, trial, roots)
    spy = InspectableTestOnlyRunner(frozen)
    def changing_runner(*args):
        if not spy.seen:
            p = roots[frozen["challenger_artifact_id"]] / "model.json"
            obj = json.loads(p.read_text(encoding="utf-8"))
            obj["fixture_id"] = "SWAPPED_MID_RUN"
            _write(p, obj)
        return spy(*args)
    with pytest.raises(SealedExecutionRejected,
                       match="R101_MODEL_BUNDLE_MUTATED_DURING_EXECUTION"):
        execute_fixture_pair(seal, frozen, eq, manifest, trial, raws, roots,
                             fixture_runner=changing_runner, explicit_fixture_mode=True)


def test_r101_rejects_cross_role_physical_asset_before_executor_call(tmp_path):
    eq, manifest, trial, raws, frozen, roots = _fixture(tmp_path)
    seal = seal_fixture_execution(frozen, trial, roots)
    held = next(r for r in manifest["records"] if r["role"] == "VALIDATION")
    held["physical_id"] = manifest["records"][0]["physical_id"]
    runner = InspectableTestOnlyRunner(frozen)
    with pytest.raises(ValueError, match="R93_PHYSICAL_DEVICE_CROSSES_DATA_ROLES"):
        execute_fixture_pair(seal, frozen, eq, manifest, trial, raws, roots,
                             fixture_runner=runner, explicit_fixture_mode=True)
    assert runner.seen == []
